// muapi Studio "Apps" as templates.
//
// Turns src/data/muapiStudioAppsMap.json (generated by scripts/build-muapi-apps-map.mjs)
// plus our own prompts (src/data/muapiAppPrompts.json, original wording, not muapi's)
// into entries in the normal template schema, so they show up in the Templates gallery
// and open in the Template Studio like every other template.
//
// Notes:
//  - ids are prefixed `muapi-` so they can never collide with existing templates.
//  - `niche` is deliberately not set: TemplatesPage puts niche templates in a separate section.
//  - Select inputs list the default first (the studio treats options[0] as the default).
import appsMap from '../data/muapiStudioAppsMap.json';
import prompts from '../data/muapiAppPrompts.json';

export const MUAPI_APP_CATEGORIES = Object.freeze({
  'professional': 'App · Professional',
  'enhance-style': 'App · Enhance & Style',
  'face-identity': 'App · Face & Identity',
  'video-editing': 'App · Video Editing',
  'ads': 'App · Ads & Products',
  'games-characters': 'App · Games & Characters',
  'trending-templates': 'App · Trending',
});

const CATEGORY_ICONS = {
  'professional': '🎥',
  'enhance-style': '✨',
  'face-identity': '🧑',
  'video-editing': '✂️',
  'ads': '📣',
  'games-characters': '🎮',
  'trending-templates': '🔥',
};

const V2V_MODELS = new Set(['ai-video-face-swap', 'video-background-remover']);

/** Put `first` at the front of a list (if present) and de-duplicate. */
function defaultFirst(list, first) {
  const strs = list.map(String);
  const f = String(first);
  return strs.includes(f) ? [f, ...strs.filter((x) => x !== f)] : strs;
}

/** Evenly spaced option values for a slider, default first. */
function sliderValues({ min, max, default: def }) {
  const span = max - min;
  const raw = [min, min + span / 4, def, min + (3 * span) / 4, max].map((v) => Math.round(v));
  return [...new Set([def, ...raw])];
}

function fill(template, value) {
  return template.split('{value}').join(String(value));
}

function mediaInput(m) {
  switch (m.key) {
    case 'images_list':
    case 'image_url':
      return { name: 'image_url', type: 'image', label: m.label, required: !!m.required };
    case 'last_image':
    case 'last_image_url':
      return { name: 'last_image', type: 'frame', label: m.label, required: false };
    case 'swap_url':
      return { name: 'swap_url', type: 'image', label: m.label, required: !!m.required };
    case 'video_url':
      return { name: 'video_url', type: 'video', label: m.label, required: !!m.required };
    default:
      return { name: m.key, type: m.type === 'video' ? 'video' : 'image', label: m.label, required: !!m.required };
  }
}

export function buildMuapiAppTemplate(app, promptData = prompts) {
  const s = app.studio;
  const model = app.endpoint.targetModel || app.endpoint.model;
  const isVideo = app.mediaType === 'video';
  const modelType = V2V_MODELS.has(app.endpoint.model) ? 'v2v' : isVideo ? 'i2v' : 'i2i';

  const inputs = s.mediaInputs.map(mediaInput);

  const presetPhrases = promptData.presets?.[app.id];
  if (s.presets.length && presetPhrases) {
    inputs.push({
      name: 'style_preset',
      type: 'select',
      label: 'Style',
      options: s.presets.map((p) => `${p.label} — ${presetPhrases[p.label] ?? p.label}`),
    });
  }

  for (const sl of s.sliders) {
    const phrase = promptData.sliderPhrases?.[sl.key];
    if (!phrase) continue;
    inputs.push({
      name: `adj_${sl.key}`,
      type: 'select',
      label: sl.unit ? `${sl.label} (${sl.unit})` : sl.label,
      options: sliderValues(sl).map((v) => (v === sl.default ? 'no change' : fill(phrase, v))),
    });
  }

  for (const p of s.parameters) {
    if (!p.options?.length) continue;
    inputs.push({
      name: p.key,
      type: 'select',
      label: p.label || p.key,
      options: defaultFirst(p.options, p.default),
    });
  }

  if (s.requiresPrompt !== false) {
    inputs.push({
      name: 'prompt',
      type: 'textarea',
      label: 'Extra details (optional)',
      placeholder: 'Anything specific you want in the result…',
    });
  }

  const basePrompt = promptData.apps?.[app.id] || (s.requiresPrompt === false ? '{prompt}' : `${app.description}. {prompt}`);

  const template = {
    id: `muapi-${app.id}`,
    name: app.name,
    description: app.description,
    category: MUAPI_APP_CATEGORIES[app.studioCategoryKey],
    icon: CATEGORY_ICONS[app.studioCategoryKey] || '🎬',
    outputType: isVideo ? 'video' : 'image',
    model,
    modelType,
    inputs,
    basePrompt,
    defaultParams: { ...(s.defaultParams || {}) },
    // Where this came from and what it costs; read by the cost line and the docs.
    muapiApp: {
      slug: app.id,
      status: app.status,
      endpoint: app.endpoint.path,
      defaultCostUsd: s.defaultCostUsd,
      // Dedicated tools can carry a test note (e.g. Skin Enhancer's backend error); the studio
      // shows `warning` to the user, `notes` keeps the technical detail.
      ...(app.notes && app.status === 'endpoint'
        ? { notes: app.notes, warning: 'This tool may be temporarily unavailable: muapi returned a backend error for it in our last test.' }
        : {}),
    },
  };

  const aspect = s.parameters.find((p) => p.key === 'aspect_ratio');
  if (aspect) template.aspectRatio = String(aspect.default ?? aspect.options?.[0] ?? '1:1');
  return template;
}

export const MUAPI_APP_TEMPLATES = Object.freeze(appsMap.apps.map((a) => buildMuapiAppTemplate(a)));

export function getMuapiAppTemplateBySlug(slug) {
  return MUAPI_APP_TEMPLATES.find((t) => t.muapiApp.slug === slug) || null;
}
